#include <deque>
#include <iostream>
#include <stdexcept>

int main() {
    std::deque<int> d = {10, 20, 30};

    // 1. Unchecked Access (Fast)
    std::cout << "Element 1: " << d[1] << std::endl;

    // 2. Checked Access (Safe)
    try {
        std::cout << "Element 3: " << d.at(3) << std::endl; 
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    // d[5]; // DANGER: Undefined Behavior
}
